#include <string>
#include <algorithm>

class Solution {
    bool isVowel(char c) {
        return c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u';
    }
public:
    int maxVowels(std::string s, int k) {
        int cur = 0;
        for (int i = 0; i < k; ++i) if (isVowel(s[i])) cur++;
        int maxV = cur;
        for (int i = k; i < (int)s.size(); ++i) {
            if (isVowel(s[i])) cur++;
            if (isVowel(s[i - k])) cur--;
            maxV = std::max(maxV, cur);
        }
        return maxV;
    }
};

class Solution {
    private boolean isVowel(char c) {
        return c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u';
    }
    public int maxVowels(String s, int k) {
        int cur = 0;
        for (int i = 0; i < k; i++) if (isVowel(s.charAt(i))) cur++;
        int maxV = cur;
        for (int i = k; i < s.length(); i++) {
            if (isVowel(s.charAt(i))) cur++;
            if (isVowel(s.charAt(i - k))) cur--;
            maxV = Math.max(maxV, cur);
        }
        return maxV;
    }
}

var maxVowels = function(s, k) {
    const vowels = new Set(['a', 'e', 'i', 'o', 'u']);
    let cur = 0;
    for (let i = 0; i < k; i++) if (vowels.has(s[i])) cur++;
    let maxV = cur;
    for (let i = k; i < s.length; i++) {
        if (vowels.has(s[i])) cur++;
        if (vowels.has(s[i - k])) cur--;
        if (cur > maxV) maxV = cur;
    }
    return maxV;
};
